#!/usr/bin/env python3
"""Serialize the independently written cote2 claim assessments; no inferred verdicts."""
import json,csv,datetime
from pathlib import Path
P=Path(__file__).resolve().parent
I={int(x['id'].split('-')[-1]):x for x in json.loads((P/'items.json').read_text())}
C=[];events=[]
who='GPT-6 Astra Pro; effort not independently exposed; SA23-20261119/root'
def c(n,items,status,cls,fate,date,refs,present,comp='No scalar computation is required; see the stated argument and exact source.',confidence='high',statement=None,his=None,proof=None,refined=None):
    xs=[I[i] for i in items];cid=f'C-SA23-root-{n:03}'
    x=dict(id=cid,items=[a['id'] for a in xs],cote='2',scans=sorted(set(sum([a['scans'] for a in xs],[]))),lines=sum([a['lines'] for a in xs],[]),his_statement=his or '; '.join(a['his_words'] for a in xs),statement=statement or xs[0]['statement'],status_on_pages=status,computation=comp,**{'class':cls},fate=fate,fate_date=date,present_status='As of 19 November 2026: '+present,refs=refs,confidence=confidence)
    C.append(x)
    events.append([cid,'2026-11-19',who,'used and rechecked in this run','Matched the actual source scope to the opened references; '+present+' This event is a statement/hypothesis check, not a new proof.'])
    if proof:events.append([cid,'2026-11-19',who,'targeted proof check' if proof.startswith('Targeted proof check:') else 'independent re-proof',proof])
    if comp.startswith('computations.py'):events.append([cid,'2026-11-19',who,'computation or formal certificate',comp])
    if refined:events.append([cid,'2026-11-19',who,'refuted, with refined statement id','Literal interpretation refuted under the explicitly stated hypotheses. Refined statement: '+refined+'. '+present])
    return x

